//! Tiberian Dawn's built-in object data.
//!
//! Tiberian Dawn has no rules file: every object's statistics are compiled in as
//! constructor arguments in the `*DATA.CPP` files, and weapons and warheads are tables in
//! `CONST.CPP`. [`objects`] holds those values exactly as written (generated by
//! `rust/tools/gen_td_data.py`); the accessors here look them up by type.
//!
//! Not yet ported: the infantry animation `do_table`s, and the art-derived values the game
//! computes at load time (dimensions, turret offsets from shapes).

pub mod enums;
pub mod objects;
pub mod tracks;

pub use enums::{Anim, Armor, BuildingSize, Bullet, Land, Locomotion, Rtti, Voc, Warhead, Weapon};
pub use objects::{
    AIRCRAFT, AircraftData, BUILDINGS, BULLETS, BuildingData, BulletData, GROUND, GroundData,
    INFANTRY, InfantryData, OVERLAYS, OverlayData, TEMPLATES, TERRAINS, TemplateData, TerrainData,
    UNITS, UnitData, WARHEADS, WEAPONS, WarheadData, WeaponData,
};

use crate::{
    AircraftType, BuildingType, House, InfantryType, OverlayType, TemplateType, TerrainType,
    Theater, UnitType,
};

impl UnitType {
    /// This vehicle's built-in data.
    #[must_use]
    pub fn data(self) -> &'static UnitData {
        &UNITS[usize::from(self.id())]
    }
}

impl InfantryType {
    /// This infantry type's built-in data.
    #[must_use]
    pub fn data(self) -> &'static InfantryData {
        &INFANTRY[usize::from(self.id())]
    }
}

impl BuildingType {
    /// This building's built-in data.
    #[must_use]
    pub fn data(self) -> &'static BuildingData {
        &BUILDINGS[usize::from(self.id())]
    }
}

impl AircraftType {
    /// This aircraft's built-in data.
    #[must_use]
    pub fn data(self) -> &'static AircraftData {
        &AIRCRAFT[usize::from(self.id())]
    }
}

impl Bullet {
    /// This projectile's built-in data.
    #[must_use]
    pub fn data(self) -> &'static BulletData {
        &BULLETS[usize::from(self.id())]
    }
}

impl Weapon {
    /// This weapon's built-in data.
    #[must_use]
    pub fn data(self) -> &'static WeaponData {
        &WEAPONS[usize::from(self.id())]
    }
}

impl Warhead {
    /// This warhead's built-in data.
    #[must_use]
    pub fn data(self) -> &'static WarheadData {
        &WARHEADS[usize::from(self.id())]
    }

    /// Damage against `armor`, in 1/256ths (`Modifier[]`; 256 is full damage).
    #[must_use]
    pub fn modifier(self, armor: Armor) -> u16 {
        self.data().modifier[usize::from(armor.id())]
    }
}

impl TemplateType {
    /// This template's built-in data.
    #[must_use]
    pub fn data(self) -> &'static TemplateData {
        &TEMPLATES[usize::from(self.id())]
    }
}

impl TemplateData {
    /// The ground under one of this template's icons.
    #[must_use]
    pub fn land_at(&self, icon: u8) -> Land {
        if self.alt_icons.contains(&icon) {
            self.alt_land
        } else {
            self.land
        }
    }

    /// Whether the template exists in `theater`.
    #[must_use]
    pub fn in_theater(&self, theater: Theater) -> bool {
        self.theaters & (1 << theater.id()) != 0
    }
}

impl TerrainType {
    /// This terrain object's built-in data.
    #[must_use]
    pub fn data(self) -> &'static TerrainData {
        &TERRAINS[usize::from(self.id())]
    }
}

impl TerrainData {
    /// Whether the object exists in `theater` (placing it elsewhere fails).
    #[must_use]
    pub fn in_theater(&self, theater: Theater) -> bool {
        self.theaters & (1 << theater.id()) != 0
    }
}

impl OverlayType {
    /// This overlay's built-in data.
    #[must_use]
    pub fn data(self) -> &'static OverlayData {
        &OVERLAYS[usize::from(self.id())]
    }
}

impl Land {
    /// How this ground affects movement and building.
    #[must_use]
    pub fn ground(self) -> &'static GroundData {
        &GROUND[usize::from(self.id())]
    }

    /// Speed over this ground for `locomotion`, 0 (impassable) to 255 (full speed).
    #[must_use]
    pub fn speed(self, locomotion: Locomotion) -> u8 {
        self.ground().speed[usize::from(locomotion.id())]
    }

    /// Whether `locomotion` can cross this ground at all.
    #[must_use]
    pub fn passable(self, locomotion: Locomotion) -> bool {
        self.speed(locomotion) != 0
    }
}

/// The ground of a cell from what's on it (`CellClass::Recalc_Attributes`).
///
/// An overlay decides it unless it leaves the ground clear (walls and Tiberium do; crates
/// and the like don't); then the template icon, which may be one of the template's
/// alternate icons (a shoreline's beach edge, say); and an empty cell is clear.
#[must_use]
pub fn cell_land(template: Option<(TemplateType, u8)>, overlay: Option<OverlayType>) -> Land {
    if let Some(overlay) = overlay {
        let land = overlay.data().ground;
        if land != Land::Clear {
            return land;
        }
    }
    match template {
        Some((template, icon)) => template.data().land_at(icon),
        None => TemplateType::Clear1.data().land,
    }
}

impl BuildingData {
    /// Hit points: the constructor doubles buildings' written strength.
    #[must_use]
    pub fn max_strength(&self) -> u32 {
        u32::from(self.strength) * 2
    }

    /// Whether `building` is one of this building's prerequisites.
    #[must_use]
    pub fn requires(&self, building: BuildingType) -> bool {
        self.prerequisites & (1 << building.id()) != 0
    }
}

macro_rules! ownable {
    ($($data:ty),*) => {$(
        impl $data {
            /// Whether `house` may own this type.
            #[must_use]
            pub fn ownable_by(&self, house: House) -> bool {
                self.owners & (1 << house.id()) != 0
            }
        }
    )*};
}
ownable!(UnitData, InfantryData, BuildingData, AircraftData);

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn tables_are_indexed_by_type() {
        for &unit in UnitType::ALL {
            assert_eq!(unit.data().kind, unit);
            assert_eq!(unit.data().ini_name, unit.name());
        }
        for &infantry in InfantryType::ALL {
            assert_eq!(infantry.data().kind, infantry);
        }
        for &building in BuildingType::ALL {
            assert_eq!(building.data().kind, building);
            assert_eq!(building.data().ini_name, building.name());
        }
        for &aircraft in AircraftType::ALL {
            assert_eq!(aircraft.data().kind, aircraft);
        }
        for &weapon in Weapon::ALL {
            assert_eq!(weapon.data().kind, weapon);
        }
        for &warhead in Warhead::ALL {
            assert_eq!(warhead.data().kind, warhead);
        }
        for &template in TemplateType::ALL {
            assert_eq!(template.data().kind, template);
            assert_eq!(template.data().ini_name, template.name());
        }
        for &terrain in TerrainType::ALL {
            assert_eq!(terrain.data().kind, terrain);
            assert_eq!(terrain.data().ini_name, terrain.name());
        }
        for &overlay in OverlayType::ALL {
            assert_eq!(overlay.data().kind, overlay);
            assert_eq!(overlay.data().ini_name, overlay.name());
        }
    }

    #[test]
    fn medium_tank() {
        let mtnk = UnitType::Mtank.data();
        assert_eq!(mtnk.strength, 400);
        assert_eq!(mtnk.cost, 800);
        assert_eq!(mtnk.primary, Some(Weapon::T105mm));
        assert_eq!(mtnk.secondary, None);
        assert_eq!(mtnk.armor, Armor::Steel);
        assert_eq!(mtnk.locomotion, Some(Locomotion::Track));
        assert_eq!(mtnk.max_speed, 18);
        assert!(mtnk.is_turret_equipped);
        assert!(mtnk.ownable_by(House::Good));
        assert!(!mtnk.ownable_by(House::Bad));
        assert!(Weapon::T105mm.data().attack > 0);
    }

    #[test]
    fn weapons_factory() {
        let weap = BuildingType::Weap.data();
        assert_eq!(weap.drain, 30);
        assert_eq!(weap.size, BuildingSize::T33);
        assert_eq!(weap.occupy, &[64, 65, 66, 128, 129, 130]);
        assert!(weap.requires(BuildingType::Refinery));
        assert_eq!(weap.builds, Rtti::Unittype);
        assert_eq!(weap.max_strength(), u32::from(weap.strength) * 2);
    }

    #[test]
    fn cell_ground() {
        // Shore templates are water except the icons listed as beach.
        let shore = TemplateType::Shore1;
        assert_eq!(cell_land(Some((shore, 0)), None), Land::Beach);
        assert_eq!(cell_land(Some((shore, 8)), None), Land::Water);
        assert_eq!(cell_land(None, None), Land::Clear);
        // Walls and Tiberium override the template; ground they leave clear doesn't.
        let water = Some((TemplateType::Water, 0));
        assert_eq!(cell_land(water, Some(OverlayType::SandbagWall)), Land::Wall);
        assert_eq!(
            cell_land(None, Some(OverlayType::Tiberium1)),
            Land::Tiberium
        );
        assert_eq!(cell_land(water, Some(OverlayType::WoodCrate)), Land::Water);
        assert!(TemplateType::Shore1.data().in_theater(Theater::Temperate));
        assert!(!TemplateType::Shore1.data().in_theater(Theater::Desert));
    }

    #[test]
    fn ground_speeds() {
        assert!(Land::Road.speed(Locomotion::Wheel) > 0);
        assert!(!Land::Water.passable(Locomotion::Track));
        assert!(Land::Water.passable(Locomotion::Float));
        assert!(!Land::Clear.passable(Locomotion::Float));
        assert!(Land::Rock.passable(Locomotion::Winged));
        // Foot soldiers are quicker on roads than on clear ground.
        assert!(Land::Road.speed(Locomotion::Foot) > Land::Clear.speed(Locomotion::Foot));
        assert!(Land::Clear.ground().buildable && !Land::Tiberium.ground().buildable);
    }

    #[test]
    fn patch_values_win() {
        // DEFINES.H defines PATCH, so the turret costs the patched 600, not 250.
        assert_eq!(BuildingType::Turret.data().cost, 600);
        assert_eq!(BuildingType::Turret.data().strength, 200);
    }

    #[test]
    fn sniper_bullet_keeps_its_quirk() {
        // `ClassSniper` passes BULLET_BULLET as its type but sits in the BULLET_SNIPER slot.
        assert_eq!(Bullet::Sniper.data().kind, Bullet::Bullet);
        assert_eq!(Bullet::Bullet.data().kind, Bullet::Bullet);
    }

    #[test]
    fn warhead_modifiers() {
        // Small arms do full damage to unarmoured targets and little to steel.
        assert_eq!(Warhead::Sa.modifier(Armor::None), 256);
        assert!(Warhead::Sa.modifier(Armor::Steel) < 256);
    }
}
